export default function isValidParentheses(s) {
  if (typeof s !== 'string') {
    throw new TypeError('isValidParentheses expects a string');
  }
  const closerFor = { '(': ')', '[': ']', '{': '}' };
  const expected = [];
  for (const ch of s) {
    if (ch === '(' || ch === '[' || ch === '{') {
      expected.push(closerFor[ch]);
    } else if (ch === ')' || ch === ']' || ch === '}') {
      if (expected.pop() !== ch) {
        return false;
      }
    }
  }
  return expected.length === 0;
}

