export default function isValidParentheses(s) {
  if (typeof s !== 'string') {
    throw new TypeError('isValidParentheses expects a string');
  }
  let rest = s.replace(/[^()[\]{}]/g, '');
  let before;
  do {
    before = rest;
    rest = rest.replace(/\(\)|\[\]|\{\}/g, '');
  } while (rest !== before);
  return rest === '';
}
